import{_ as s,o as t,c as i,l as a,t as n,N as o}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"ipp-usb | x-cmd man (ip man8) | Daemon for IPP over USB printer support","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ipp-usb - Daemon for IPP over USB printer support","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipp-usb | x-cmd man (ip man8) | Daemon for IPP over USB printer support"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ipp-usb - Daemon for IPP over USB printer support"}]]},"headers":[],"params":{"isMan":true,"man":"ipp-usb","category":"ip man8","desc":"Daemon for IPP over USB printer support"},"relativePath":"ip/man8/ipp-usb.md","filePath":"ip/man8/ipp-usb.md"}'),r={name:"ip/man8/ipp-usb.md"},l={class:"visually-hidden"},d=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p><strong>ipp-usb</strong> - Daemon for IPP over USB printer support</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ipp-usb</strong> daemon enables driver-less printing and scanning on USB-only AirPrint-compatible printers and MFPs.</p><p>It works by connecting to the device by USB using IPP-over-USB protocol, and exposing the device to the network, including DNS-SD (ZeroConf) advertising.</p><p>IPP printing, eSCL scanning and web console are fully supported.</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><h3 id="usage" tabindex="-1">Usage: <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage:&quot;">​</a></h3><p><strong>ipp-usb mode [options]</strong></p><h3 id="modes-are" tabindex="-1">Modes are: <a class="header-anchor" href="#modes-are" aria-label="Permalink to &quot;Modes are:&quot;">​</a></h3><dl><dt><strong>standalone</strong></dt><dd>run forever, automatically discover IPP-over-USB devices and serve them all</dd><dt><strong>udev</strong></dt><dd>like standalone, but exit when last IPP-over-USB device is disconnected</dd><dt><strong>debug</strong></dt><dd>logs duplicated on console, -bg option is ignored</dd><dt><strong>check</strong></dt><dd>check configuration and exit. It also prints a list of all connected devices</dd><dt><strong>status</strong></dt><dd>print status of the running <strong>ipp-usb</strong> daemon, including information of all connected devices</dd></dl><h3 id="options-are" tabindex="-1">Options are <a class="header-anchor" href="#options-are" aria-label="Permalink to &quot;Options are&quot;">​</a></h3><dl><dt><strong>-bg</strong></dt><dd>run in background (ignored in debug mode)</dd></dl><h2 id="networking" tabindex="-1">NETWORKING <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;NETWORKING&quot;">​</a></h2><p>Essentially, <strong>ipp-usb</strong> makes printer or scanner accessible from the network, converting network-side HTTP operations to the USB operations.</p><p>By default, <strong>ipp-usb</strong> exposes device only to the loopback interface, using the <strong>localhost</strong> address (both <strong>127.0.0.1</strong> and <strong>::1</strong>, for IPv4 and IPv6, respectively). TCP ports are allocated automatically, and allocation is persisted in the association with the particular device, so the next time the device is plugged on, it will get the same port. The default port range for TCP ports allocation is <strong>60000-65535</strong>.</p><p>This default behavior can be changed, using configuration file. See <strong>CONFIGURATION</strong> section below for details.</p><p>If you decide to publish your device to the real network, the following things should be taken into consideration:</p><ol><li><p>Your <strong>private</strong> device will become <strong>public</strong> and it will become accessible by other computers from the network</p></li><li><p>Firewall rules needs to be updated appropriately. The <strong>ipp-usb</strong> daemon will not do it automatically by itself</p></li><li><p>IPP over USB specification explicitly require that the <strong>Host</strong> field in the HTTP request is set to <strong>localhost</strong> or <strong>localhost:port</strong>. If device is accessed from the real network, <strong>Host</strong> header will reflect the real network address. Most of devices allow it, but some are more restrictive and will not work in this configuration.</p></li></ol><p>:</p><h2 id="dns-sd-avahi-integration" tabindex="-1">DNS-SD (AVAHI INTEGRATION) <a class="header-anchor" href="#dns-sd-avahi-integration" aria-label="Permalink to &quot;DNS-SD (AVAHI INTEGRATION)&quot;">​</a></h2><p>IPP over USB is intended to be used with the automatic device discovery, and for this purpose <strong>ipp-usb</strong> advertises all devices it handles, using DNS-SD protocol. On Linux, DNS-SD is handled with a help of Avahi daemon.</p><p>DNS-SD advertising can be disabled via configuration file. Also, if Avahi is not installed or not running, <strong>ipp-usb</strong> will still work correctly, although DNS-SD advertising will not work.</p><p>For every device the following services will be advertised:</p><hr><p>Instance Type Subtypes Device name _ipp._tcp _universal._sub._ipp._tcp Device name _printer._tcp   Device name _uscan._tcp   Device name _http._tcp   BBPP _ipp-usb._tcp</p><hr><p>Notes:</p><dl><dt>○</dt><dd><strong>Device name</strong> is the name under which device appears in the list of available devices, for example, in the printing dialog (it is DNS-SD device name, in another words), and for most of devices will match the device&#39;s model name. It is appended with the <strong>&quot; (USB)&quot;</strong> suffix, so if device is connected via network and via USB simultaneously, these two connections can be easily distinguished. If there are two devices with the same name connected simultaneously, the suffix becomes <strong>&quot; (USB NNN)&quot;</strong>, with NNN number unique for each device, for disambiguation. In another words, the single <strong>&quot;Kyocera ECOSYS M2040dn&quot;</strong> device will be listed as <strong>&quot;Kyocera ECOSYS M2040dn (USB)&quot;</strong>, and two such a devices will be listed as <strong>&quot;Kyocera ECOSYS M2040dn (USB 1)&quot;</strong> and <strong>&quot;Kyocera ECOSYS M2040dn (USB 2)&quot;</strong></dd><dt>○</dt><dd><strong>_ipp._tcp</strong> and <strong>_printer._tcp</strong> are only advertises for printer devices and MFPs</dd><dt>○</dt><dd><strong>_uscan._tcp</strong> is only advertised for scanner devices and MFPs</dd><dt>○</dt><dd>for the <strong>_ipp._tcp</strong> service, the <strong>_universal._sub._ipp._tcp</strong> subtype is also advertised for iOS compatibility</dd><dt>○</dt><dd><strong>_printer._tcp</strong> is advertised with TCP port set to 0. Other services are advertised with the actual port number</dd><dt>○</dt><dd><strong>_http._tcp</strong> is device web-console. It is always advertises in assumption it is always exist</dd><dt>○</dt><dd><strong>BBPP</strong>, used for the <strong>_ipp-usb._tcp</strong> service, is the USB bus (BB) and port (PP) numbers in hex. The purpose of this advertising is to help CUPS and other possible &quot;clients&quot; to guess which devices are handled by the <strong>ipp-usb</strong> service, to avoid possible conflicts with the legacy USB drivers.</dd></dl><p>:</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p><strong>ipp-usb</strong> searched for its configuration file in two places:</p><ol><li><p><strong>/etc/ipp-usb/ipp-usb.conf</strong></p></li><li><p><strong>ipp-usb.conf</strong> in the directory where executable file is located</p></li></ol><p>:</p><p>Configuration file syntax is very similar to .INI files syntax. It consist of named sections, and each section contains a set of named variables. Comments are started from # or ; characters and continues until end of line:</p><p>:</p><pre><code># This is a comment
[section 1]
variable 1 = value 1  ; and another comment
variable 2 = value 2
</code></pre><p>:</p><h3 id="network-parameters" tabindex="-1">Network parameters <a class="header-anchor" href="#network-parameters" aria-label="Permalink to &quot;Network parameters&quot;">​</a></h3><p>Network parameters are all in the <strong>[network]</strong> section:</p><p>:</p><pre><code>[network]
  # TCP ports for HTTP will be automatically allocated in the
  # following range
  http-min-port = 60000
  http-max-port = 65535
</code></pre><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Enable or disable DNS-SD advertisement</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  dns-sd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # enable | disable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Network interface to use. Set to \`all\` if you want to expose you</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # printer to the local network. This way you can share your printer</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # with other computers in the network, as well as with iOS and</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Android devices.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  interface</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loopback</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # all | loopback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Enable or disable IPv6</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ipv6</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable#</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> disable</span></span></code></pre></div><p>:</p><h3 id="logging-configuration" tabindex="-1">Logging configuration <a class="header-anchor" href="#logging-configuration" aria-label="Permalink to &quot;Logging configuration&quot;">​</a></h3><p>Logging parameters are all in the <strong>[logging]</strong> section:</p><p>:</p><pre><code>[logging]
  # device-log  - what logs are generated per device
  # main-log    - what common logs are generated
  # console-log - what of generated logs goes to console
  #
  # parameter contains a comma-separated list of
  # the following keywords:
  #   error     - error messages
  #   info      - informative messages
  #   debug     - debug messages
  #   trace-ipp, trace-escl, trace-http - very detailed
  #               per-protocol traces
  #   trace-usb - hex dump of all USB traffic
  #   all       - all logs
  #   trace-all - alias to all
  #
  # Note, trace-* implies debug, debug implies info, info implies
  # error
  device-log    = all
  main-log      = debug
  console-log   = debug
</code></pre><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Log rotation parameters:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #   log-file-size- max log file before rotation. Use suffix</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #  M for megabytes or K for kilobytes</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #   log-backup-files - how many backup files to preserve during</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #  rotation</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  max-file-size</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 256K</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  max-backup-files</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Enable or disable ANSI colors on console</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  console-color</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # enable | disable</span></span></code></pre></div><p>:</p><h3 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h3><p>Some devices, due to their firmware bugs, require special handling, called device-specific <strong>quirks</strong>. <strong>ipp-usb</strong> loads quirks from the <strong>/usr/share/ipp-usb/quirks/*.conf</strong> files and from the <strong>/etc/ipp-usb/quirks/*.conf</strong> files. The <strong>/etc/ipp-usb/quirks</strong> directory is for system quirks overrides or admin changes. These files have .INI-file syntax with the content that looks like this:</p><p>:</p><pre><code>[HP LaserJet MFP M28-M31]
  http-connection = keep-alive
</code></pre><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[HP OfficeJet Pro 8730]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  http-connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> close</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[HP Inc. HP Laser MFP 135a]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default configuration</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  http-connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span></code></pre></div><p>:</p><p>For each discovered device, its model name is matched against sections of the quirks files. Section names may contain glob-style wildcards: <em><em>*</em> * that matches any sequence of characters and <strong>?</strong> , that matches any single character. To match one of these characters (</em>*** * and <strong>?</strong>) literally, use backslash as escape.</p><p>Note, the simplest way to guess the exact model name for the particular device is to use <strong>ipp-usb check</strong> command, which prints a list of all connected devices.</p><p>All matching sections from all quirks files are taken in consideration, and applied in priority order. Priority is computed using the following algorithm:</p><dl><dt>○</dt><dd>When matching model name against section name, amount of non-wildcard matched characters is counted, and the longer match wins</dd><dt>○</dt><dd>Otherwise, section loaded first wins. Files are loaded in alphabetical order, sections read sequentially</dd></dl><p>:</p><p>If some parameter exist in multiple sections, used its value from the most priority section</p><p>The following parameters are defined:</p><dl><dt>○</dt><dd><strong>blacklist = true | false</strong> <br> If <strong>true</strong>, the matching device is ignored by the <strong>ipp-usb</strong></dd><dt>○</dt><dd><strong>http-XXX = YYY</strong> <br> Set XXX header of the HTTP requests forwarded to device to YYY. If YYY is empty string, XXX header is removed</dd><dt>○</dt><dd><strong>usb-max-interfaces = N</strong> <br> Don&#39;t use more that N USB interfaces, even if more is available</dd><dt>○</dt><dd><strong>disable-fax = true | false</strong> <br> If <strong>true</strong>, the matching device&#39;s fax capability is ignored</dd><dt>○</dt><dd><strong>init-reset = none | soft | hard</strong> <br> How to reset device during initialization. Default is <strong>none</strong></dd><dt>○</dt><dd><strong>init-delay = NNN</strong> <br> Delay, in milliseconds, between device is opened and, optionally, reset, and the first request is sent to device</dd><dt>○</dt><dd><strong>request-delay</strong> = NNN <br> Delay, in milliseconds, between subsequent requests</dd></dl><p>:</p><p>If you found out about your device that it needs a quirk to work properly or it does not work with <strong>ipp-usb</strong> at all, although it provides IPP-over-USB interface, please report the issue at <a href="https://github.com/OpenPrinting/ipp-usb" target="_blank" rel="noreferrer">https://github.com/OpenPrinting/ipp-usb</a>. It will let us to update our collection of quirks, so helping other owners of such a device.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt>○</dt><dd><strong>/etc/ipp-usb/ipp-usb.conf</strong>: the daemon configuration file</dd><dt>○</dt><dd><strong>/var/log/ipp-usb/main.log</strong>: the main log file</dd><dt>○</dt><dd><strong>/var/log/ipp-usb/&lt;DEVICE&gt;.log</strong>: per-device log files</dd><dt>○</dt><dd><strong>/var/ipp-usb/dev/&lt;DEVICE&gt;.state</strong>: device state (HTTP port allocation, DNS-SD name)</dd><dt>○</dt><dd><strong>/var/ipp-usb/lock/ipp-usb.lock</strong>: lock file, that helps to prevent multiple copies of daemon to run simultaneously</dd><dt>○</dt><dd><strong>/var/ipp-usb/ctrl</strong>: <strong>ipp-usb</strong> control socket. Currently only used to obtain the per-device status (printed by <strong>ipp-usb status</strong>), but its functionality may be extended in a future</dd><dt>○</dt><dd><strong>/usr/share/ipp-usb/quirks/*.conf</strong>: device-specific quirks (see above)</dd><dt>○</dt><dd><strong>/etc/ipp-usb/quirks/*.conf</strong>: device-specific quirks defined by sysadmin (see above)</dd></dl><p>:</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright (c) by Alexander Pevzner (<a href="mailto:pzz@apevzner.com" target="_blank" rel="noreferrer">pzz@apevzner.com</a>, <a href="mailto:pzz@pzz.msk.ru" target="_blank" rel="noreferrer">pzz@pzz.msk.ru</a>) <br> All rights reserved.</p><p>This program is licensed under 2-Clause BSD license. See LICENSE file for details.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>cups(1)</strong></p>`,74);function p(e,h,c,g,u,k){return t(),i("div",null,[a("h1",l,n(e.$params.man),1),d])}const f=s(r,[["render",p]]);export{b as __pageData,f as default};
